$(document).ready(function(){$("#processToPayment").click(function(e){e.preventDefault(),$("#processToPayment").hide();$("#couponCode").val();var o=$(".shipping-box").serializeArray();o.push({name:"type",value:"order"}),o.push({name:"action",value:"generate"}),o.push({name:"order",value:$("#orderId").val()}),o.push({name:"paymentMode",value:$("#paymentMode").val()}),$.ajax({type:"POST",dataType:"json",data:o,success:function(e){200==e.status?window.location.href=e.url:console.log("Success : ",e),$("#processToPayment").show()},error:function(e){console.log("error : ",e),$("#processToPayment").show()}})})});